#!/usr/bin/env python3
"""Final manual source-collation refinements, not an automatic verdict generator."""
import json, copy
from pathlib import Path
O=Path(__file__).resolve().parents[1]
C=json.loads((O/'claims.json').read_text()); cm={int(x['id'].split('-')[-1]):x for x in C}
def change(n,**kw): cm[n].update(kw)
change(125,references=['Stacks0FPP:21.48','Stacks03TI:Proposition64.10.2, full proof of homotopy and model independence'])
change(131,references=['Stacks020Z:Lemma34.3.14, retraction of big to small Zariski topos','SGA4VII:4.1, analogous étale comparison'],literature_fate='The supplied proof checks the unit on opens. Stacks34.3.14 explicitly gives the small/big Zariski retraction; SGA4VII4.1 is the analogous étale comparison. Neither result identifies the entire big topos with the small topos.')
change(133,references=['Stacks005T:Definition5.18.1 and Lemma5.18.7, open/closed subset correspondence'],literature_fate='The Jacobson hypothesis makes every nonempty locally closed subset contain a point closed in X. Stacks5.18.1 and5.18.7 verify the exact open-lattice comparison. Equality of the open locales gives equivalence of their sheaf topoi; it does not give a bijection of their original point sets.')
change(187,literature_fate='Illusie1994 §3 formulates the weight–monodromy problem. Kato/Lu–Zheng2019 AppendixA.2 proves alternating Weil-trace independence and integrality, not all individual-degree assertions. The author-hosted Ito–Zou preprint dated2026-10-06, Theorem4.4, proves weight–monodromy for hyper-Kähler varieties over finite extensions of Qp, including p-adic coefficients. This specific subcase does not settle the general manuscript question.',references=['Illusie1994:§3','Kato2019:AppendixA.2','ItoZou2026:TheoremB/4.4, hyper-Kähler scope; preprint'])
change(208,references=['Faltings1983:§1, introductory results(a),(b),printedp349','MilneAV:IV2.5–2.7, reduction to finiteness','MilneCM:3.3, commutant criterion'],literature_fate='Established for number fields by Faltings semisimplicity and the endomorphism theorem (1983, §1(a),(b)): after finite extension, a connected solvable reductive image is a torus, and its commutant contains a commutative semisimple algebra of dimension2dimA. The CM criterion then applies. Faltings’s original paper and its statements were opened; publication October1983, no first-circulation date asserted. The characteristic-zero function-field version also needs the constant-part reduction.')
change(209,references=['DeligneWeilII:Corollary3.4.13, geometric semisimplicity','MilneCM:4.7, Mumford–Tate/CM distinction','ItoZou2026:TheoremA/2.5, hyper-Kähler subcase; preprint'],literature_fate='Geometric semisimplicity for smooth proper direct images is established by Deligne. Arithmetic semisimplicity for general geometric Galois representations remains a stronger question. Ito–Zou’s author preprint dated2026-10-06 proves it in all degrees for hyper-Kähler varieties over fields finitely generated over Q (Theorem2.5), a specific subcase. No single universal motivic theorem is specified by the manuscript.')
change(213,references=['SGA7IX:5.12.1–5.13,printedpp387–388; ordinary inertia translation explicitly restricted to ell≠p','SerreTate1968:Theorem2, potential good reduction source','Illusie1994:1.4, geometric quasi-unipotence'],literature_fate='For ell distinct from residue characteristic, original SGA7IX5.12.1 identifies Barsotti–Tate reduction properties with inertia properties, and5.13 gives the abelian-variety reduction criterion. Quasi-unipotence plus semisimplicity makes the inertia image finite; finite images are semisimple in characteristic zero. Original5.13 was visually collated, while its ell=p wording is explicitly about Barsotti–Tate objects and is not the same representation-theoretic assertion.')
change(214,references=['Katz1981:Theorem2.1 and extension construction,printedpp148–153','BrinonConrad2009:8.3.6–8.3.7, nonsplit crystalline examples','SGA7IX:5.12.1–5.13, distinction between BT and ordinary inertia criteria'])
change(228,literature_fate='Original SGA7I, redacted by Deligne, Theorem3.5 (printedp12) gives echelon2 for H¹ of smooth projective curves; Remark3.6 gives the abelian-variety version; Remark3.7 (printedp13) states echelon2 for H¹ of every finite-type X. These original pages were visually collated. Thus the published general bound2 is stronger than the draft bound3 at34:82. The concluding H² at34:81 conflicts with the announced H¹ reduction and remains a scan question.',references=['SGA7I:Theorem3.5 and Remarks3.6–3.7,printedpp12–13, original facsimile visually read','Illusie1994:1.4, geometric monodromy'],confidence='high')
# A publication catalogue is not an identification of the reused editorial sheet.
for n in list(range(150,156))+list(range(231,241)):
 c=cm[n]
 c['references']=['BourbakiEVT:official bibliography,1981 collected chapters1–5; exact Tribu63 edition unidentified','GrothEVT1954:separate bibliographic lead, not identification of the sheet']
 c['literature_fate']=c['literature_fate'].replace('Bibliography identifies Grothendieck1954 EVT as a possible source family only.','The Tribu63 label suggests Bourbaki editorial material; the official Bourbaki catalogue and Grothendieck bibliography were both checked, but the exact earlier edition remains unidentified.').replace('Grothendieck EVT catalogue and standard separation searches do not resolve the edition.','The Bourbaki and Grothendieck bibliographic searches do not resolve the exact edition.')
if 241 not in cm:
 x=copy.deepcopy(cm[233]); x.update(id='C-SA13-241',title='Extending the extreme-point corollary to a cap',items=[],scans=['33:155'],lines=[{'file':'pro/MPL_33_147-181+34_002-017_transcription.tex','cote':33,'scan':155,'start':249,'end':249}],his_statement='Exercice: dans le cor., remplacer $x$ par un chapeau.',modern_statement='The editorial exercise asks to replace the extreme point by a cap in the preceding corollary. The old corollary and exact definition of chapeau are not supplied, so no unique stronger theorem is reconstructed.',page_status='open on the pages',classification='F',reconstruction='This is an exercise on the reused EVT sheet, not an independently attributed conjecture of Grothendieck.',literature_fate='The official Bourbaki catalogue, Grothendieck EVT bibliography and exact Tribu63/EVT searches did not identify the source edition or missing cap definition. The point version is checked in C-SA13-233, but that does not determine this extension.',confidence='low')
 C.append(x); cm[241]=x
for c in C:
 for a,b in [('statement','modern_statement'),('status_on_pages','page_status'),('class','classification'),('fate','literature_fate'),('present_status','literature_fate'),('computation','computations')]:c[a]=c[b]
 c['refs']=list(dict.fromkeys(s.split(':',1)[0] for s in c['references']))
(O/'claims.json').write_text(json.dumps(C,ensure_ascii=False,indent=2)+'\n')
print('Saved',len(C),'claims; exact SGA7, Faltings, Katz, Stacks and current preprint scopes refined.')
